54: 
55:     fprintf(out, "%dx%d\n", s->width, s->height);
56:     fprintf(out, "пикселей: %lld\n", s->pixel_count);
57:     fprintf(out, "средний цвет: %3d %3d %3d\n", avg_r, avg_g, avg_b);
58:     fprintf(out, "мин. яркость: %.1f\n", s->y_min);
