8: #include <print>
9: 
10: using namespace raster::common;
11: 
12: namespace raster::stats {
13: 
14: Stats compute_stats(const Image& img) {
15:     Stats s{};
16:     s.width = img.width();
17:     s.height = img.height();
18:     s.max_val = img.max_val();
19: 
20:     bool first_pixel = true;
21: 
22:     for (const auto& p : img.pixels()) {
23:         int32_t r = p.r;
24:         int32_t g = p.g;
25:         int32_t b = p.b;
26: 
27:         s.total_r += r;
28:         s.total_g += g;
29:         s.total_b += b;
30: 
31:         double y = luma(r, g, b);
32: 
33:         if (first_pixel) {
34:             s.y_min = y;
35:             s.y_max = y;
36:             first_pixel = false;
37:         } else {
38:             if (y < s.y_min)
39:                 s.y_min = y;
40:             if (y > s.y_max)
41:                 s.y_max = y;
42:         }
43: 
44:         int32_t bin = (int32_t)(y * 8.0 / (s.max_val + 1));
45:         if (bin >= 8)
46:             bin = 7;
47:         ++s.histogram[bin];
48:         ++s.pixel_count;
49:     }
50: 
51:     return s;
52: }
53: 
54: void ppm_print_stats(const Stats& s, std::ostream& os) {
55:     int32_t avg_r = (int32_t)((double)s.total_r / s.pixel_count + 0.5);
56:     int32_t avg_g = (int32_t)((double)s.total_g / s.pixel_count + 0.5);
57:     int32_t avg_b = (int32_t)((double)s.total_b / s.pixel_count + 0.5);
58: 
59:     std::println(os, "{}x{}", s.width, s.height);
60:     std::println(os, "пикселей: {}", s.pixel_count);
61:     std::println(os, "средний цвет: {:3d} {:3d} {:3d}", avg_r, avg_g, avg_b);
62:     std::println(os, "мин. яркость: {:.1f}", s.y_min);
63:     std::println(os, "макс. яркость: {:.1f}", s.y_max);
64:     std::println(os, "гистограмма яркости:");
65: 
66:     for (int32_t i = 0; i < 8; ++i) {
67:         double bin_width = (double)(s.max_val + 1) / 8.0;
68:         int32_t lo = (int32_t)(i * bin_width);
69:         int32_t hi = (i == 7) ? s.max_val : (int32_t)((i + 1) * bin_width) - 1;
70:         std::println(os, "  [{:3d},{:3d}]: {}", lo, hi, s.histogram[i]);
71:     }
72: }
73: 
74: } // namespace raster::stats
