31:         pixel_to_grayscale(&img->pixels[i], &img->pixels[i]);
32: }
33: 
34: void apply_threshold(struct Image* img, int threshold) {
35:     for (long long i = 0; i < (long long)img->width * img->height; ++i)
36:         pixel_threshold(&img->pixels[i], threshold, &img->pixels[i]);
37: }
