43:     std::string_view arg = args[1];
44: 
45:     if (arg == "--help")
46:         return FilterParseResult{.request = FilterRequest::kHelp};
47: 
48:     if (arg == "--version")
49:         return FilterParseResult{.request = FilterRequest::kVersion};
50: 
51:     if (arg == "--grayscale") {
52:         if (args.size() > 2) {
53:             std::println(stderr, "--grayscale не принимает аргументов");
54:             return std::nullopt;
55:         }
56:         return FilterParseResult{.args = FilterArgs{FilterMode::kGrayscale}};
57:     }
58: 
59:     if (arg == "--threshold") {
60:         if (args.size() < 3) {
61:             std::println(stderr, "--threshold требует аргумента T");
62:             return std::nullopt;
63:         }
64: 
65:         int t{};
66:         auto [ptr, ec] = std::from_chars(args[2].data(), args[2].data() + args[2].size(), t);
67:         if (ec != std::errc{} || ptr != args[2].data() + args[2].size()) {
68:             std::println(stderr, "T должен быть целым числом; получено: {}", args[2]);
69:             return std::nullopt;
70:         }
71: 
72:         if (t < 0 || t > 255) {
73:             std::println(stderr, "T должен быть в [0; 255]; получено: {}", t);
74:             return std::nullopt;
75:         }
76: 
77:         return FilterParseResult{.args = FilterArgs{FilterMode::kThreshold, t}};
78:     }
79: 
80:     std::println(stderr, "неизвестный аргумент: {}. используйте --grayscale или --threshold T",
81:                  arg);
82:     return std::nullopt;
83: }
84: 
85: void print_filter_usage(std::ostream& os) {
86:     std::println(os, "Использование: filter --grayscale | --threshold T");
87:     std::println(os);
88:     std::println(os, "Читает PPM P3 из stdin, пишет валидный PPM в stdout.");
89:     std::println(os);
90:     std::println(os, "Режимы:");
91:     std::println(os, "  --grayscale     конверсия в оттенки серого по luma");
92:     std::println(os, "  --threshold T   бинаризация по порогу яркости (0 <= T <= 255)");
93:     std::println(os);
94:     std::println(os, "Опции:");
95:     std::println(os, "  --help          показать справку");
96:     std::println(os, "  --version       показать версию");
97: }
98: 
99: void print_filter_version(std::ostream& os) { std::println(os, "filter {}", kVersion); }
100: 
101: int run_filter(std::span<const std::string_view> args, std::istream& input, std::ostream& output) {
102:     auto parsed = parse_filter_args(args);
103:     if (!parsed)
104:         return std::to_underlying(ExitCode::kUsage);
105: 
106:     if (parsed->request == FilterRequest::kHelp) {
107:         print_filter_usage(output);
108:         return std::to_underlying(ExitCode::kOk);
109:     }
110: 
111:     if (parsed->request == FilterRequest::kVersion) {
112:         print_filter_version(output);
113:         return std::to_underlying(ExitCode::kOk);
114:     }
115: 
116:     const FilterArgs& filter_args = parsed->args;
117:     auto result = Image::read(input);
118:     if (!result.value.has_value()) {
119:         std::println(stderr, "{}", result.diagnostic);
120:         switch (result.value.error()) {
121:         case PpmReadError::kEmptyInput:
122:             return std::to_underlying(ExitCode::kNoInput);
123:         case PpmReadError::kIOError:
124:             return std::to_underlying(ExitCode::kIOErr);
125:         case PpmReadError::kAllocError:
126:             return std::to_underlying(ExitCode::kData);
127:         default:
128:             return std::to_underlying(ExitCode::kData);
129:         }
130:     }
131: 
132:     auto& image = *result.value;
133: 
134:     switch (filter_args.mode) {
135:     case FilterMode::kGrayscale:
136:         apply_grayscale(image);
137:         break;
138:     case FilterMode::kThreshold:
139:         apply_threshold(image, filter_args.threshold);
140:         break;
141:     }
142: 
143:     PpmWriter writer(output, image.width(), image.height());
144:     auto header = writer.putHeader();
145:     if (!header.value) {
146:         std::println(stderr, "{}", header.diagnostic);
147:         return std::to_underlying(ExitCode::kIOErr);
148:     }
149:     auto res = writer.putAll(image.pixels(), /*finalize=*/true);
150:     if (!res.value) {
151:         std::println(stderr, "{}", res.diagnostic);
152:         switch (res.value.error()) {
153:         case PpmWriteError::kIOError:
154:             return std::to_underlying(ExitCode::kIOErr);
155:         case PpmWriteError::kTooManyPixels:
156:         case PpmWriteError::kNotEnoughPixels:
157:             return std::to_underlying(ExitCode::kData);
158:         }
159:     }
160: 
161:     auto f = writer.flush();
162:     if (!f.value) {
163:         std::println(stderr, "{}", f.diagnostic);
164:         return std::to_underlying(ExitCode::kIOErr);
165:     }
166: 
167:     return std::to_underlying(ExitCode::kOk);
168: }
169: 
170: } // namespace raster::filter
