12: void pixel_to_grayscale(const struct Pixel* src, struct Pixel* dst) {
13:     double y = luma(src->r, src->g, src->b);
14:     uint8_t yb = (uint8_t)(y + 0.5);
15:     dst->r = yb;
16:     dst->g = yb;
17:     dst->b = yb;
18: }
19: 
20: void pixel_threshold(const struct Pixel* src, int threshold, struct Pixel* dst) {
21:     double y = luma(src->r, src->g, src->b);
22:     if (y > threshold) {
23:         dst->r = dst->g = dst->b = 255;
24:     } else {
25:         dst->r = dst->g = dst->b = 0;
26:     }
27: }
28: 
29: void apply_grayscale(struct Image* img) {
30:     for (long long i = 0; i < (long long)img->width * img->height; ++i)
31:         pixel_to_grayscale(&img->pixels[i], &img->pixels[i]);
32: }
33: 
34: void apply_threshold(struct Image* img, int threshold) {
35:     for (long long i = 0; i < (long long)img->width * img->height; ++i)
36:         pixel_threshold(&img->pixels[i], threshold, &img->pixels[i]);
37: }
38: 
39: int parse_filter_args(int argc, char** argv, struct FilterParseResult* out_result) {
40:     if (argc < 2) {
41:         fprintf(stderr, "использование: filter --grayscale | --threshold T\n");
42:         return -1;
43:     }
44: 
45:     if (strcmp(argv[1], "--help") == 0) {
46:         out_result->request = FILTER_HELP;
47:         return 0;
48:     }
49: 
50:     if (strcmp(argv[1], "--version") == 0) {
51:         out_result->request = FILTER_VERSION;
52:         return 0;
53:     }
54: 
55:     out_result->request = FILTER_RUN;
56: 
57:     if (strcmp(argv[1], "--grayscale") == 0) {
58:         if (argc > 2) {
59:             fprintf(stderr, "--grayscale не принимает аргументов\n");
60:             return -1;
61:         }
62:         out_result->args.mode = FILTER_GRAYSCALE;
63:         return 0;
64:     }
65: 
66:     if (strcmp(argv[1], "--threshold") == 0) {
67:         if (argc < 3) {
68:             fprintf(stderr, "--threshold требует аргумента T\n");
69:             return -1;
70:         }
71: 
72:         char* end = NULL;
73:         long t = strtol(argv[2], &end, 10);
74:         if (end == argv[2] || *end != '\0') {
75:             fprintf(stderr, "T должен быть целым числом; получено: %s\n", argv[2]);
76:             return -1;
77:         }
78: 
79:         if (t < 0 || t > 255) {
80:             fprintf(stderr, "T должен быть в [0; 255]; получено: %ld\n", t);
81:             return -1;
82:         }
83: 
84:         out_result->args.mode = FILTER_THRESHOLD;
85:         out_result->args.threshold = (int)t;
86:         return 0;
87:     }
88: 
89:     fprintf(stderr, "неизвестный аргумент: %s. используйте --grayscale или --threshold T\n",
90:             argv[1]);
91:     return -1;
92: }
93: 
94: void print_filter_usage(FILE* out) {
95:     fprintf(out, "Использование: filter --grayscale | --threshold T\n");
96:     fprintf(out, "\n");
97:     fprintf(out, "Читает PPM P3 из stdin, пишет валидный PPM в stdout.\n");
98:     fprintf(out, "\n");
99:     fprintf(out, "Режимы:\n");
100:     fprintf(out, "  --grayscale     конверсия в оттенки серого по luma\n");
101:     fprintf(out, "  --threshold T   бинаризация по порогу яркости (0 <= T <= 255)\n");
102:     fprintf(out, "\n");
103:     fprintf(out, "Опции:\n");
104:     fprintf(out, "  --help          показать справку\n");
105:     fprintf(out, "  --version       показать версию\n");
106: }
107: 
108: void print_filter_version(FILE* out) { fprintf(out, "filter %s\n", KV_VERSION); }
109: 
110: int run_filter(int argc, char** argv, FILE* input, FILE* output) {
111:     struct FilterParseResult parsed;
112:     if (parse_filter_args(argc, argv, &parsed) != 0)
113:         return EC_USAGE;
114: 
115:     if (parsed.request == FILTER_HELP) {
116:         print_filter_usage(output);
117:         return EC_OK;
118:     }
119: 
120:     if (parsed.request == FILTER_VERSION) {
121:         print_filter_version(output);
122:         return EC_OK;
123:     }
124: 
125:     struct FilterArgs args = parsed.args;
126:     struct PpmResult result = ppm_read(input);
127:     if (result.error != PRE_OK) {
128:         fprintf(stderr, "%s\n", result.diagnostic);
129:         int ec = EC_DATA;
130:         if (result.error == PRE_EMPTY_INPUT)
131:             ec = EC_NOINPUT;
132:         else if (result.error == PRE_IO_ERROR)
133:             ec = EC_IOERR;
134:         return ec;
135:     }
136: 
137:     struct Image* image = &result.image;
138: 
139:     switch (args.mode) {
140:     case FILTER_GRAYSCALE:
141:         apply_grayscale(image);
142:         break;
143:     case FILTER_THRESHOLD:
144:         apply_threshold(image, args.threshold);
145:         break;
146:     }
147: 
148:     struct PpmWriter writer;
149:     ppm_writer_init(&writer, output, image->width, image->height);
150:     for (long long i = 0; i < (long long)image->width * image->height; ++i)
151:         ppm_writer_put(&writer, image->pixels[i].r, image->pixels[i].g, image->pixels[i].b);
152: 
153:     if (ppm_writer_finish(&writer) != 0) {
154:         char errbuf[256];
155:         safe_strerror(errno, errbuf, sizeof errbuf);
156:         fprintf(stderr, "сбой записи в поток: %s (errno %d)\n", errbuf, errno);
157:         ppm_image_free(image);
158:         return EC_IOERR;
159:     }
160: 
161:     ppm_image_free(image);
162:     return EC_OK;
163: }
