39:         std::println(stderr, "использование: filter --grayscale | --threshold T");
40:         return std::nullopt;
41:     }
42: 
43:     std::string_view arg = args[1];
44: 
45:     if (arg == "--help")
46:         return FilterParseResult{.request = FilterRequest::kHelp};
47: 
48:     if (arg == "--version")
49:         return FilterParseResult{.request = FilterRequest::kVersion};
50: 
51:     if (arg == "--grayscale") {
52:         if (args.size() > 2) {
53:             std::println(stderr, "--grayscale не принимает аргументов");
54:             return std::nullopt;
55:         }
56:         return FilterParseResult{.args = FilterArgs{FilterMode::kGrayscale}};
57:     }
58: 
59:     if (arg == "--threshold") {
60:         if (args.size() < 3) {
61:             std::println(stderr, "--threshold требует аргумента T");
62:             return std::nullopt;
63:         }
64: 
65:         int t{};
66:         auto [ptr, ec] = std::from_chars(args[2].data(), args[2].data() + args[2].size(), t);
67:         if (ec != std::errc{} || ptr != args[2].data() + args[2].size()) {
68:             std::println(stderr, "T должен быть целым числом; получено: {}", args[2]);
69:             return std::nullopt;
70:         }
71: 
72:         if (t < 0 || t > 255) {
73:             std::println(stderr, "T должен быть в [0; 255]; получено: {}", t);
74:             return std::nullopt;
75:         }
76: 
77:         return FilterParseResult{.args = FilterArgs{FilterMode::kThreshold, t}};
78:     }
79: 
80:     std::println(stderr, "неизвестный аргумент: {}. используйте --grayscale или --threshold T",
81:                  arg);
82:     return std::nullopt;
83: }
