613: class ControllableBuf : public std::streambuf {
614:   public:
615:     void fail_with(int e) {
616:         fail_ = true;
617:         err_ = e;
618:     }
619: 
620:   protected:
621:     int_type overflow(int_type c) override {
622:         if (fail_) {
623:             errno = err_;
624:             return traits_type::eof();
625:         }
626:         if (c != traits_type::eof())
627:             data_ += static_cast<char>(c);
628:         return traits_type::not_eof(c);
629:     }
630:     int sync() override {
