49: class ControllableBuf : public std::streambuf {
50:   public:
51:     void fail_with(int e) {
52:         fail_ = true;
53:         err_ = e;
54:     }
55: 
56:   protected:
57:     int_type overflow(int_type c) override {
58:         if (fail_) {
59:             errno = err_;
60:             return traits_type::eof();
61:         }
62:         if (c != traits_type::eof())
63:             data_ += static_cast<char>(c);
64:         return traits_type::not_eof(c);
65:     }
66:     int sync() override {
67:         if (fail_) {
68:             errno = err_;
69:             return -1;
70:         }
71:         return 0;
72:     }
73: 
74:   private:
75:     bool fail_ = false;
76:     int err_ = 0;
77:     std::string data_;
78: };
79: 
80: class FlushFailBuf : public std::streambuf {
81:   protected:
82:     int_type overflow(int_type c) override {
83:         if (c != traits_type::eof())
84:             data_ += static_cast<char>(c);
85:         return traits_type::not_eof(c);
86:     }
87:     int sync() override {
88:         errno = EPIPE;
89:         return -1;
90:     }
91: 
92:   private:
93:     std::string data_;
94: };
95: 
96: class SilentFailBuf : public std::streambuf {
97:   protected:
98:     int_type overflow(int_type) override { return traits_type::eof(); }
99:     int sync() override { return -1; }
100: };
