109:     check(r.diagnostic.find(std::string{"(errno "} + std::to_string(err) + ")") !=
110:               std::string::npos,
111:           std::string(name) + ": errno");
112:     check(r.diagnostic.find(std::generic_category().message(err)) != std::string::npos,
113:           std::string(name) + ": system text");
114: }
