60: StatsWriteResult ppm_print_stats(const Stats& s, std::ostream& os) {
61:     int32_t avg_r = (int32_t)((double)s.total_r / s.pixel_count + 0.5);
62:     int32_t avg_g = (int32_t)((double)s.total_g / s.pixel_count + 0.5);
