69:     std::println(os, "мин. яркость: {:.1f}", s.y_min);
70:     std::println(os, "макс. яркость: {:.1f}", s.y_max);
71:     std::println(os, "гистограмма яркости:");
72: 
73:     for (int32_t i = 0; i < 8; ++i) {
74:         double bin_width = (double)(s.max_val + 1) / 8.0;
75:         int32_t lo = (int32_t)(i * bin_width);
76:         int32_t hi = (i == 7) ? s.max_val : (int32_t)((i + 1) * bin_width) - 1;
77:         std::println(os, "  [{:3d},{:3d}]: {}", lo, hi, s.histogram[i]);
78:     }
79: 
80:     os.flush();
81:     if (os.bad() || os.fail()) {
82:         int e = errno;
83:         std::string diagnostic;
