97:     auto result = Image::read(input);
98:     if (!result.value) {
99:         std::println(stderr, "{}", result.diagnostic);
100:         switch (result.value.error()) {
101:         case PpmReadError::kEmptyInput:
102:             return std::to_underlying(ExitCode::kNoInput);
103:         case PpmReadError::kIOError:
104:             return std::to_underlying(ExitCode::kIOErr);
105:         case PpmReadError::kAllocError:
106:             return std::to_underlying(ExitCode::kData);
107:         default:
108:             return std::to_underlying(ExitCode::kData);
109:         }
110:     }
111: 
112:     Stats stats = compute_stats(*result.value);
113:     auto printed = ppm_print_stats(stats, output);
114:     if (!printed.value) {
115:         std::println(stderr, "{}", printed.diagnostic);
116:         return std::to_underlying(ExitCode::kIOErr);
117:     }
118: 
119:     return std::to_underlying(ExitCode::kOk);
120: }
121: 
122: } // namespace raster::stats

